struct stringx { char data[8]; ~stringx(); };
struct anim_info {
    float percent;
    stringx anim;
    int damage;
    float recover_time;
    float recover_var;
    int flags;
    ~anim_info() {}
};

template<class T> struct vector2 {
    T* start;
    T* finish;
    T* end_of_storage;
    ~vector2() {
        for (T* p = start; p != finish; ++p)
            p->~T();
        if (start)
            deallocate(start, end_of_storage - start);
    }
    static void deallocate(T*, unsigned int);
};

struct pair_value { stringx first; vector2<anim_info> second; };
struct node {
    node* free_next;
    node* parent;
    node* left;
    node* right;
    pair_value value;
};
struct allocator_state { char pad[12]; node* head; };
extern allocator_state allocator_state_instance;
asm(".equ allocator_state_instance,0x003E5628");
asm(".equ _$_7stringx,0x0034D6E0");

struct Tree;
extern "C" void recurse(Tree*, node*) __asm__("recurse_alias");
asm(".equ recurse_alias,0x00142CF8");

struct Tree {
    void erase(node*) __asm__("_M_erase__t8_Rb_tree5Z7stringxZt4pair2ZC7stringxZt6vector2ZQ219animation_interface9anim_infoZt12my_allocator1ZQ219animation_interface9anim_infoZt10_Select1st1Zt4pair2ZC7stringxZt6vector2ZQ219animation_interface9anim_infoZt12my_allocator1ZQ219animation_interface9anim_infoZQ219animation_interface9s_t_s_t_rZt12my_allocator1Zt6vector2ZQ219animation_interface9anim_infoZt12my_allocator1ZQ219animation_interface9anim_infoPt13_Rb_tree_node1Zt4pair2ZC7stringxZt6vector2ZQ219animation_interface9anim_infoZt12my_allocator1ZQ219animation_interface9anim_info");
};

void Tree::erase(node* x) {
    while (x != 0) {
        recurse(this, x->right);
        node* y = x->left;
        x->value.~pair_value();
        x->free_next = allocator_state_instance.head;
        allocator_state_instance.head = x;
        x = y;
    }
}
